 */
class BingoBoardWindow extends JFrame
{
	private final IronsPubBingoPlugin plugin;
	private final JLabel statusLabel = new JLabel();
	private final BingoGridPanel grid = new BingoGridPanel();
	private static final int DETAIL_WIDTH = 380;
	private final BingoTileDetail detail;
	private final JScrollPane detailScroll;
	private final JSplitPane split;
	private final List<BingoTileCell> cells = new ArrayList<>();
	private final List<JLabel> cellIcons = new ArrayList<>();
	private final List<BingoWrappedLabel> cellLabels = new ArrayList<>();
	private BingoBoard renderedBoard;
	private final javax.swing.Timer countdownTimer;

	BingoBoardWindow(IronsPubBingoPlugin plugin)
	{
		this.plugin = plugin;
		setTitle("Irons Pub Bingo");
		setIconImage(ImageUtil.loadImageResource(IronsPubBingoPlugin.class, "window_icon.png"));
		setDefaultCloseOperation(HIDE_ON_CLOSE);
		setSize(700, 780);
		setMinimumSize(new Dimension(420, 480));

		JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		statusLabel.setFont(FontManager.getRunescapeFont());
		statusLabel.setForeground(Color.WHITE);
		content.add(statusLabel, BorderLayout.NORTH);

		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				refresh(); // re-wrap tile labels to the new cell width
			}
		});
		// The same tile detail as the sidebar, under the board, for the selected tile.
		// It keeps the sidebar's fixed content width inside a centering holder - all its
		// wrap widths and bar labels are computed for that basis, and stretching it to
		// the window width breaks them. The split divider lets the player trade board
		// space against detail space instead of the detail claiming a fixed strip.
		detail = new BingoTileDetail(plugin, DETAIL_WIDTH);
		JPanel detailHolder = new JPanel(new java.awt.GridBagLayout());
		detailHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		detailHolder.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		java.awt.GridBagConstraints holderConstraints = new java.awt.GridBagConstraints();
		holderConstraints.anchor = java.awt.GridBagConstraints.NORTHWEST;
		holderConstraints.weightx = 1;
		holderConstraints.weighty = 1;
		detailHolder.add(detail, holderConstraints);
		detailScroll = new JScrollPane(detailHolder,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		detailScroll.setBorder(BorderFactory.createEmptyBorder());
		detailScroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		detailScroll.setPreferredSize(new Dimension(0, 260));
		detailScroll.setVisible(false);

		split = new JSplitPane(JSplitPane.VERTICAL_SPLIT, grid, detailScroll);
		split.setResizeWeight(1.0);
		split.setBorder(null);
		split.setDividerSize(0);
		split.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(split, BorderLayout.CENTER);
		setContentPane(content);

		// Keeps the "Time left" countdown in the status line ticking while visible.
		countdownTimer = new javax.swing.Timer(1000, e ->
		{
			if (isVisible())
			{
				updateStatusLine();
			}
		});
		countdownTimer.start();
	}

	@Override
	public void dispose()
	{
		countdownTimer.stop();
		super.dispose();
	}

	void open()
	{
		setAlwaysOnTop(plugin.popOutAlwaysOnTop());
		refresh();
		setVisible(true);
		toFront();
	}

	void refresh()
	{
		BingoBoard board = plugin.getBoard();
		if (board != renderedBoard)
		{
			rebuildGrid(board);
			renderedBoard = board;
		}
		if (board == null)
		{
			setTitle("Irons Pub Bingo");
			statusLabel.setText("No board loaded");
			detailScroll.setVisible(false);
			split.setDividerSize(0);
			return;
		}

		detail.setSelectedTile(plugin.selectedTileIndex());
		boolean showDetail = detail.rebuild();
		if (detailScroll.isVisible() != showDetail)
		{
			detailScroll.setVisible(showDetail);
			split.setDividerSize(showDetail ? 6 : 0);
			if (showDetail)
			{
				split.resetToPreferredSizes();
			}
			getContentPane().revalidate();
		}
		detail.revalidate();
		detail.repaint();

		setTitle("Irons Pub Bingo - " + board.getName());
		updateStatusLine();

		int size = board.getSize();
		// Actual cell width: grid width minus the inter-cell gaps, minus padding. Swing's
		// HTML renderer honors width only on <body>, and an over-wide block would render
		// left-anchored and clipped, pushing the text off center.
		int gridWidth = grid.getWidth() > 0 ? grid.getWidth() : 640;
		int textWidth = Math.max(48, (gridWidth - (size - 1) * 4) / size - 16);
		boolean drawLines = plugin.lineDisplay() == LineDisplay.LINES;
		boolean fillMode = plugin.progressFill();
		int selected = plugin.selectedTileIndex();
		grid.setLines(size, drawLines ? plugin.completedLineSegments() : java.util.Collections.emptyList());
		java.util.Set<Integer> lineCells = drawLines ? java.util.Collections.emptySet() : plugin.completedLineCells();
		for (int i = 0; i < cells.size(); i++)
		{
			BingoTile tile = board.getTiles().get(i);
			BingoTileCell cell = cells.get(i);
			boolean complete = plugin.isTileComplete(i);
			cell.setBackground(complete ? BingoUi.COLOR_COMPLETE
				: !fillMode && hasProgress(tile, i) ? BingoUi.COLOR_PARTIAL : BingoUi.COLOR_EMPTY);
			cell.setFillFraction(complete || !fillMode ? 0f : (float) plugin.tileProgressFraction(i));
			Color border = i == selected ? Color.WHITE
				: lineCells.contains(i) ? BingoUi.COLOR_LINE
				: ColorScheme.DARKER_GRAY_HOVER_COLOR;
			cell.setBorder(BorderFactory.createLineBorder(border,
				i == selected || lineCells.contains(i) ? 2 : 1));
			cellLabels.get(i).setWrapWidth(textWidth);
			String tooltip = "<html><b>" + BingoUi.escapeHtml(tile.label) + "</b><br>"
				+ (complete ? "Complete" : summary(tile, i)) + "</html>";
			cell.setToolTipText(tooltip);
			cellIcons.get(i).setToolTipText(tooltip);
			cellLabels.get(i).setToolTipText(tooltip);
		}
		revalidate();
		repaint();
	}

	private void updateStatusLine()
	{
		BingoBoard board = plugin.getBoard();
		if (board == null)
		{
			return;
		}
		StringBuilder status = new StringBuilder(plugin.boardTitleText())
			.append("   |   ").append(plugin.completedCount()).append('/').append(board.getTiles().size()).append(" tiles")
			.append("   |   ").append(plugin.completedLines()).append(" lines");
		if (plugin.totalBoardPoints() > 0)
		{
			status.append("   |   ").append(plugin.earnedPoints()).append('/').append(plugin.totalBoardPoints()).append(" pts");
		}
		String event = plugin.eventStatusText();
		if (!event.isEmpty())
		{
			status.append("   |   ").append(event);
		}
		String text = status.toString();
		if (!text.equals(statusLabel.getText()))
		{
			statusLabel.setText(text);
		}
	}

	private void rebuildGrid(BingoBoard board)
	{
		grid.removeAll();
		cells.clear();
		cellIcons.clear();
		cellLabels.clear();
		if (board == null)
		{
			grid.setLayout(new BorderLayout());
			JLabel hint = new JLabel("Import a board in the Irons Pub Bingo side panel first.", SwingConstants.CENTER);
			hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			grid.add(hint, BorderLayout.CENTER);
		}
		else
		{
			int size = board.getSize();
			grid.setLayout(new GridLayout(size, size, 4, 4));
			for (int i = 0; i < board.getTiles().size(); i++)
			{
				final int tileIndex = i;
				BingoTile tile = board.getTiles().get(i);
				BingoTileCell cell = new BingoTileCell();
				// Icon and text as separately stacked, individually centered components —
				// Swing's compound icon+text label does not center HTML text reliably.
				JLabel iconLabel = new JLabel();
				iconLabel.setAlignmentX(java.awt.Component.CENTER_ALIGNMENT);
				BingoWrappedLabel label = new BingoWrappedLabel(tile.label, SwingConstants.CENTER, 100);
				label.setForeground(Color.WHITE);
				if (tile.pointsValue() > 0)
				{
					label.setSecondary(tile.pointsValue() + " pts", ColorScheme.LIGHT_GRAY_COLOR);
				}
				AsyncBufferedImage itemIcon = plugin.iconFor(tile);
				if (itemIcon != null)
				{
					BingoUi.applyIcon(iconLabel, itemIcon, 32, cell);
				}
				JPanel stack = new JPanel();
				stack.setLayout(new javax.swing.BoxLayout(stack, javax.swing.BoxLayout.Y_AXIS));
				stack.setOpaque(false);
				stack.add(iconLabel);
				stack.add(javax.swing.Box.createVerticalStrut(4));
				stack.add(label);
				cell.setLayout(new java.awt.GridBagLayout());
				cell.add(stack, new java.awt.GridBagConstraints());
				cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				// Tooltips register the children as mouse-event targets, so they must
				// carry the click handler too or they'd swallow clicks over icon/text.
				MouseAdapter click = new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						plugin.selectTileInPanel(tileIndex);
					}
				};
				cell.addMouseListener(click);
				iconLabel.addMouseListener(click);
				label.addMouseListener(click);
				cells.add(cell);
				cellIcons.add(iconLabel);
				cellLabels.add(label);
				grid.add(cell);
			}
		}
		grid.revalidate();
		grid.repaint();
	}

	private boolean hasProgress(BingoTile tile, int tileIndex)
	{
		TileProgress tp = plugin.mergedProgressFor(tileIndex);
		for (int g = 0; g < tile.goals.size(); g++)
		{
			if (tile.goals.get(g).progressOf(tp.goal(g, tile.goals.size())) > 0)
			{
				return true;
			}
		}
		return false;
	}

	private String summary(BingoTile tile, int tileIndex)
	{
		TileProgress tp = plugin.mergedProgressFor(tileIndex);
		StringBuilder sb = new StringBuilder();
		for (int g = 0; g < tile.goals.size(); g++)
		{
			BingoGoal goal = tile.goals.get(g);
			if (g > 0)
			{
				sb.append("<br>");
			}
			GoalProgress p = tp.goal(g, tile.goals.size());
			sb.append(Math.min(goal.progressOf(p), goal.target())).append('/').append(goal.target());
		}
		return sb.toString();
	}
}

package com.ironspubbingo;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Lightweight presence heartbeat, sent every couple of minutes. Liveness is judged by
 * when a session last spoke, so a dead websocket lingering on the party server (which
 * can never speak) drops out of the connected count instead of haunting it.
 */
class IronsPubBingoPing extends PartyMemberMessage
{
	String board;

	IronsPubBingoPing(String board)
	{
		this.board = board;
	}
}

package com.ironspubbingo;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Posts tile completions (message + screenshot) to a team's Discord webhook.
 * Opt-in via config; nothing is sent unless a webhook URL is set and the toggle is on.
 */
@Slf4j
@Singleton
class BingoDiscordNotifier
{
	private static final MediaType PNG = MediaType.parse("image/png");

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private DrawManager drawManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private IronsPubBingoConfig config;

	/** Whether a webhook URL is set, so callers can offer webhook-backed features. */
	boolean webhookConfigured()
	{
		return HttpUrl.parse(config.webhookUrl().trim()) != null;
	}

	/**
	 * Posts one game screenshot to the webhook as proof for a credit request and hands
	 * back a link for the request's proof field. wait=true makes Discord return the
	 * created message, and the webhook's own metadata (a GET on its URL) gives the guild
	 * and channel, which turn the message id into a jump link. The jump link never
	 * expires; attachment CDN URLs do, so they are only the fallback.
	 * The callback gets (link, error) on an arbitrary thread.
	 */
	void postProofScreenshot(String player, String requestDetail, String team,
		java.util.function.BiConsumer<String, String> callback)
	{
		HttpUrl url = HttpUrl.parse(config.webhookUrl().trim());
		if (url == null)
		{
			callback.accept(null, "No Discord webhook set");
			return;
		}
		String content = ":camera_with_flash: **" + (player == null ? "Someone" : player)
			+ "** - credit request proof: " + requestDetail + teamSuffix(team);
		drawManager.requestNextFrameListener(frame -> executor.execute(() ->
		{
			Map<String, Object> payload = new HashMap<>();
			payload.put("content", content);
			MultipartBody.Builder body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", gson.toJson(payload));
			byte[] png = toPng(frame);
			if (png == null)
			{
				callback.accept(null, "Could not capture the screenshot");
				return;
			}
			body.addFormDataPart("files[0]", "proof.png", RequestBody.create(PNG, png));
			Request post = new Request.Builder()
				.url(url.newBuilder().setQueryParameter("wait", "true").build())
				.post(body.build())
				.build();
			okHttpClient.newCall(post).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					callback.accept(null, "Discord unreachable: " + e.getMessage());
				}

				@Override
				public void onResponse(Call call, Response response) throws IOException
				{
					try (Response r = response)
					{
						if (!r.isSuccessful() || r.body() == null)
						{
							callback.accept(null, "Discord webhook returned " + r.code());
							return;
						}
						resolveMessageLink(url, gson.fromJson(r.body().string(), JsonObject.class), callback);
					}
				}
			});
		}));
	}

	/** Turns the webhook's reply into a permanent jump link, or the attachment URL. */
	private void resolveMessageLink(HttpUrl webhook, JsonObject message,
		java.util.function.BiConsumer<String, String> callback)
	{
		String messageId = message.has("id") ? message.get("id").getAsString() : null;
		String channelId = message.has("channel_id") ? message.get("channel_id").getAsString() : null;
		String attachmentUrl = null;
		if (message.has("attachments") && message.getAsJsonArray("attachments").size() > 0)
		{
			JsonObject attachment = message.getAsJsonArray("attachments").get(0).getAsJsonObject();
			attachmentUrl = attachment.has("url") ? attachment.get("url").getAsString() : null;
		}
		final String fallback = attachmentUrl;
		if (messageId == null || channelId == null)
		{
			finishWithLink(fallback, callback);
			return;
		}
		okHttpClient.newCall(new Request.Builder().url(webhook).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				finishWithLink(fallback, callback);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					String guildId = null;
					if (r.isSuccessful() && r.body() != null)
					{
						JsonObject info = gson.fromJson(r.body().string(), JsonObject.class);
						guildId = info != null && info.has("guild_id") ? info.get("guild_id").getAsString() : null;
					}
					finishWithLink(guildId == null ? fallback
						: "https://discord.com/channels/" + guildId + "/" + channelId + "/" + messageId, callback);
				}
			}
		});
	}

	private static void finishWithLink(String link, java.util.function.BiConsumer<String, String> callback)
	{
		if (link == null)
		{
			callback.accept(null, "Screenshot posted, but Discord gave no usable link");
		}
		else
		{
			callback.accept(link, null);
		}
	}

	/**
	 * Posts progress on a goal the host flagged with "screenshot": proof lands in Discord
	 * as it happens instead of one screenshot at tile completion. Rides the completion
	 * toggle and webhook - nothing extra to configure.
	 */
	void postGoalProgress(String player, String tileLabel, String goalLabel, long progress, long target,
		String team)
	{
		if (!config.postCompletions())
		{
			return;
		}
		HttpUrl url = HttpUrl.parse(config.webhookUrl().trim());
		if (url == null)
		{
			return;
		}
		String message = ":camera_with_flash: **" + (player == null ? "Someone" : player)
			+ "** - " + tileLabel + ": " + goalLabel
			+ " (" + progress + '/' + target + ')' + teamSuffix(team);
		drawManager.requestNextFrameListener(frame -> executor.execute(() -> post(url, message, frame)));
	}

	/** lootDetail: the drop (or valued loot pile) that finished the tile, or null. */
	void postCompletion(String player, String boardName, List<String> tileLabels, int completed, int total,
		String bonus, String lootDetail, String team)
	{
		if (!config.postCompletions())
		{
			return;
		}
		HttpUrl url = HttpUrl.parse(config.webhookUrl().trim());
		if (url == null)
		{
			return;
		}

		StringBuilder content = new StringBuilder();
		content.append(":tada: **").append(player == null ? "Someone" : player).append("** completed **")
			.append(String.join("**, **", tileLabels)).append("**").append(teamSuffix(team));
		content.append(" — ").append(boardName).append(" (").append(completed).append('/').append(total).append(" tiles)");
		if (lootDetail != null)
		{
			content.append("\n:package: ").append(lootDetail);
		}
		if (bonus != null)
		{
			content.append("\n:sparkles: ").append(bonus);
		}
		String message = content.toString();

		// Grab the next rendered frame as proof, then build and send the request off the client thread.
		drawManager.requestNextFrameListener(frame -> executor.execute(() -> post(url, message, frame)));
	}

	/** " for team **X**"; the caller resolves the display name (sheet > config > code). */
	private static String teamSuffix(String team)
	{
		return team == null || team.trim().isEmpty() ? "" : " for team **" + team.trim() + "**";
	}

	private void post(HttpUrl url, String message, Image frame)
	{
		Map<String, Object> payload = new HashMap<>();
		payload.put("content", message);

		MultipartBody.Builder body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", gson.toJson(payload));

		byte[] png = toPng(frame);
		if (png != null)
		{
			body.addFormDataPart("files[0]", "bingo.png", RequestBody.create(PNG, png));
		}

		Request request = new Request.Builder()
			.url(url)
			.post(body.build())
			.build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Could not post bingo completion to Discord", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (!response.isSuccessful())
				{
					log.warn("Discord webhook returned {}", response.code());
				}
				response.close();
			}
		});
	}

	private static byte[] toPng(Image frame)
	{
		try
		{
			BufferedImage image = ImageUtil.bufferedImageFromImage(frame);
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(image, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			log.warn("Could not encode bingo screenshot", e);
			return null;
		}
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Case-insensitive glob matching for item/NPC names in board files.
 * "*" matches any run of characters, so "Ancient page*" matches "Ancient page 1".
 */
final class Wildcards
{
	private Wildcards()
	{
	}

	static Pattern compile(String glob)
	{
		String[] parts = glob.split("\\*", -1);
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				sb.append(".*");
			}
			if (!parts[i].isEmpty())
			{
				sb.append(Pattern.quote(parts[i]));
			}
		}
		return Pattern.compile(sb.toString(), Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
	}

	static List<Pattern> compileAll(List<String> globs)
	{
		List<Pattern> patterns = new ArrayList<>();
		if (globs != null)
		{
			for (String glob : globs)
			{
				if (glob != null && !glob.trim().isEmpty())
				{
					patterns.add(compile(glob.trim()));
				}
			}
		}
		return patterns;
	}

	/**
	 * True if any pattern fully matches the value. An empty pattern list matches everything,
	 * so omitting e.g. "sources" on a drop goal means "from anywhere".
	 */
	static boolean anyMatch(List<Pattern> patterns, String value)
	{
		if (patterns == null || patterns.isEmpty())
		{
			return true;
		}
		if (value == null)
		{
			return false;
		}
		for (Pattern p : patterns)
		{
			if (p.matcher(value).matches())
			{
				return true;
			}
		}
		return false;
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;

/**
 * Saved progress for one tile. Serialized to profile config keyed by the board hash,
 * so each account tracks its own progress per board.
 */
public class TileProgress
{
	List<GoalProgress> goals;
	/** Player ticked the tile off by hand (manual tiles, or host-approved overrides). */
	boolean manual;
	/**
	 * When the OWNER of this progress last changed it (epoch ms). Stamped only by the owning
	 * client, so relayed/stored copies can be compared last-write-wins without clock skew
	 * issues between players.
	 */
	Long ts;

	/**
	 * A copy safe to broadcast to teammates: counters, distinct item names, the manual
	 * flag and the owner timestamp, without per-member internals (XP/kill count baselines).
	 */
	TileProgress toShare(int goalCount)
	{
		TileProgress share = new TileProgress();
		share.manual = manual;
		share.ts = ts;
		for (int g = 0; g < goalCount; g++)
		{
			GoalProgress own = goal(g, goalCount);
			GoalProgress copy = share.goal(g, goalCount);
			copy.n = own.n;
			if (own.matched != null && !own.matched.isEmpty())
			{
				copy.matched = new HashSet<>(own.matched);
			}
		}
		return share;
	}

	/**
	 * Combines the progress of several team members into one team view:
	 * counters sum ("2 uniques" = one each from two people), distinct item sets union
	 * (the same champion scroll found twice still counts once), manual ticks OR.
	 */
	static TileProgress merge(int goalCount, Collection<TileProgress> members)
	{
		TileProgress merged = new TileProgress();
		for (TileProgress member : members)
		{
			merged.manual |= member.manual;
			for (int g = 0; g < goalCount; g++)
			{
				GoalProgress from = member.goal(g, goalCount);
				GoalProgress into = merged.goal(g, goalCount);
				into.n += from.n;
				if (from.matched != null)
				{
					for (String name : from.matched)
					{
						into.addName(name);
					}
				}
			}
		}
		return merged;
	}

	/**
	 * Returns the progress slot for a goal, growing the list to the tile's goal count
	 * so boards edited between sessions do not cause index errors.
	 */
	GoalProgress goal(int index, int goalCount)
	{
		if (goals == null)
		{
			goals = new ArrayList<>();
		}
		while (goals.size() < goalCount)
		{
			goals.add(new GoalProgress());
		}
		GoalProgress p = goals.get(index);
		if (p == null)
		{
			p = new GoalProgress();
			goals.set(index, p);
		}
		return p;
	}
}

package com.ironspubbingo;

import com.google.common.collect.ImmutableSet;
import java.util.Locale;
import java.util.Set;

/**
 * The three raids and their unique ("purple") drop tables, used to detect purples
 * from loot tracker events for the raid reward chests.
 */
public enum Raid
{
	COX("chambers of xeric", ImmutableSet.of(
		"twisted bow",
		"elder maul",
		"kodai insignia",
		"dragon claws",
		"ancestral hat",
		"ancestral robe top",
		"ancestral robe bottom",
		"dinh's bulwark",
		"dexterous prayer scroll",
		"arcane prayer scroll",
		"dragon hunter crossbow",
		"twisted buckler"
	)),
	TOB("theatre of blood", ImmutableSet.of(
		"scythe of vitur",
		"ghrazi rapier",
		"sanguinesti staff",
		"justiciar faceguard",
		"justiciar chestguard",
		"justiciar legguards",
		"avernic defender hilt"
	)),
	TOA("tombs of amascut", ImmutableSet.of(
		"tumeken's shadow",
		"elidinis' ward",
		"masori mask",
		"masori body",
		"masori chaps",
		"lightbearer",
		"osmumten's fang"
	));

	private final String lootSourcePrefix;
	private final Set<String> uniques;

	Raid(String lootSourcePrefix, Set<String> uniques)
	{
		this.lootSourcePrefix = lootSourcePrefix;
		this.uniques = uniques;
	}

	/**
	 * Maps a loot tracker event source name (e.g. "Chambers of Xeric: Challenge Mode")
	 * to the raid it belongs to, or null if the source is not a raid chest.
	 */
	static Raid fromLootSource(String source)
	{
		if (source == null)
		{
			return null;
		}
		String s = source.toLowerCase(Locale.ROOT);
		for (Raid raid : values())
		{
			if (s.startsWith(raid.lootSourcePrefix))
			{
				return raid;
			}
		}
		return null;
	}

	/**
	 * Whether the given item name is one of this raid's uniques. Matched by prefix so
	 * charge variants like "Scythe of vitur (uncharged)" also count.
	 */
	boolean isUnique(String itemName)
	{
		String name = itemName.toLowerCase(Locale.ROOT);
		for (String unique : uniques)
		{
			if (name.startsWith(unique))
			{
				return true;
			}
		}
		return false;
	}
}

package com.ironspubbingo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The tile detail view: title, goals with progress bars, per-member bars, and the
 * Details/Actions foldouts. One instance lives in the sidebar panel and another under
 * the pop-out board, so both surfaces show the same thing and stay in sync.
 */
class BingoTileDetail extends JPanel
{
	/** Name suffix the team store puts on admin-credited members. */
	private static final String VERIFIED_SUFFIX = " (verified)";

	private final IronsPubBingoPlugin plugin;
	private final int widthBasis;

	private int selectedTile = -1;
	private boolean detailsExpanded;
	private boolean actionsExpanded;
	private boolean teammatesExpanded;
	/** Rebuild-scoped: the Contributors toggle renders once, above the first goal that has bars. */
	private boolean teammatesToggleAdded;
	/** A credit request is on its way to the store; the button says so meanwhile. */
	private boolean requestInFlight;

	BingoTileDetail(IronsPubBingoPlugin plugin, int widthBasis)
	{
		this.plugin = plugin;
		this.widthBasis = widthBasis;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	void setSelectedTile(int tileIndex)
	{
		selectedTile = tileIndex;
	}

	/**
	 * Rebuilds the view for the current selection.
	 *
	 * @return whether there is a tile to show (drives the surrounding card's visibility)
	 */
	boolean rebuild()
	{
		teammatesToggleAdded = false;
		removeAll();
		BingoBoard board = plugin.getBoard();
		boolean show = board != null && selectedTile >= 0 && selectedTile < board.getTiles().size();
		setVisible(show);
		if (!show)
		{
			return false;
		}

		BingoTile tile = board.getTiles().get(selectedTile);
		TileProgress merged = plugin.mergedProgressFor(selectedTile);
		TileProgress own = plugin.progressFor(selectedTile);
		boolean teamView = plugin.hasTeamData();
		Map<String, TileProgress> members = teamView ? plugin.memberProgressFor(selectedTile) : null;

		BingoWrappedLabel titleLabel = new BingoWrappedLabel(
			(plugin.showTileNumbers() ? (selectedTile + 1) + ". " : "") + tile.label, widthBasis - 44);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);
		AsyncBufferedImage itemIcon = plugin.iconFor(tile);
		if (itemIcon == null)
		{
			add(titleLabel);
		}
		else
		{
			// Fixed wrap width beside the icon: deriving it from the layout would measure
			// once before and once after the icon's width is known, and a title sitting on
			// a wrap boundary would visibly twitch between one and two lines.
			JLabel iconLabel = new JLabel();
			BingoUi.applyIcon(iconLabel, itemIcon, 32, this);
			titleLabel.setWrapWidth(widthBasis - 44);
			JPanel titleRow = new JPanel(new java.awt.BorderLayout(8, 0));
			titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			titleRow.setAlignmentX(LEFT_ALIGNMENT);
			titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
			titleRow.add(iconLabel, java.awt.BorderLayout.WEST);
			titleRow.add(titleLabel, java.awt.BorderLayout.CENTER);
			add(titleRow);
		}

		if (tile.pointsValue() > 0 || tile.goals.size() > 1)
		{
			StringBuilder meta = new StringBuilder();
			if (tile.pointsValue() > 0)
			{
				meta.append(tile.pointsValue()).append(" pts");
			}
			if (tile.goals.size() > 1)
			{
				if (meta.length() > 0)
				{
					meta.append("  ·  ");
				}
				meta.append(tile.anyMode ? "Complete ANY goal" : "Complete ALL goals");
			}
			BingoWrappedLabel metaLabel = new BingoWrappedLabel(meta.toString(), widthBasis);
			metaLabel.setForeground(ColorScheme.BRAND_ORANGE);
			add(Box.createVerticalStrut(2));
			add(metaLabel);
		}

		if (tile.description != null && !tile.description.trim().isEmpty())
		{
			BingoWrappedLabel desc = new BingoWrappedLabel(tile.description.trim(), widthBasis);
			add(Box.createVerticalStrut(4));
			add(desc);
		}

		// A manual tick overrides the bars visually; the tracked numbers underneath are
		// untouched, so unticking shows the real progress again.
		boolean ticked = merged.manual;

		add(Box.createVerticalStrut(6));
		for (int g = 0; g < tile.goals.size(); g++)
		{
			BingoGoal goal = tile.goals.get(g);
			GoalProgress p = merged.goal(g, tile.goals.size());
			boolean done = ticked || goal.isComplete(p);
			if (g > 0)
			{
				add(Box.createVerticalStrut(6));
			}

			BingoWrappedLabel goalLabel = new BingoWrappedLabel(goal.shortDescribe(), widthBasis);
			goalLabel.setForeground(done ? BingoUi.COLOR_GOAL_DONE : ColorScheme.LIGHT_GRAY_COLOR);
			if (goal.hasExtraDetail())
			{
				goalLabel.setToolTipText(goal.describe());
			}
			add(goalLabel);

			if (goal.goalType == GoalType.MANUAL)
			{
				ProgressBar manualBar = progressBar(ticked ? 1 : 0, 1, 18);
				manualBar.setCenterLabel(ticked ? "1 / 1" : "0 / 1");
				add(manualBar);
				continue;
			}

			long target = goal.target();
			long tracked = Math.min(goal.progressOf(p), target);
			long value = ticked ? target : tracked;
			ProgressBar bar = progressBar(value, target, 18);
			// Keep the real numbers visible on an overridden bar.
			bar.setCenterLabel(ticked && tracked < target
				? "Ticked  (" + formatCount(tracked) + " / " + formatCount(target) + ")"
				: formatCount(value) + " / " + formatCount(target));
			if (goal.hasExtraDetail())
			{
				bar.setToolTipText(goal.describe());
			}
			add(bar);

			if (teamView)
			{
				// Per-member bars fold away by default: on a big team they dwarf the
				// tile's own information. One toggle drives every goal's bars.
				List<MemberBar> bars = new ArrayList<>();
				for (Map.Entry<String, TileProgress> entry : members.entrySet())
				{
					long share = goal.progressOf(entry.getValue().goal(g, tile.goals.size()));
					if (share <= 0)
					{
						continue;
					}
					String memberName = entry.getKey();
					boolean verified = memberName.endsWith(VERIFIED_SUFFIX);
					if (verified)
					{
						// The "(verified)" suffix would eat the name's space - a
						// checkmark says the same thing.
						memberName = memberName.substring(0,
							memberName.length() - VERIFIED_SUFFIX.length()) + verifiedMark();
					}
					// Hand-painted: RuneLite's ProgressBar gives its left label only a
					// third of the width, truncating names long before space runs out.
					MemberBar memberBar = new MemberBar(memberName, formatCount(share),
						Math.min(1f, share / (float) target), widthBasis);
					if (verified)
					{
						memberBar.setToolTipText("Credited by an admin on the team sheet (verified progress)");
					}
					bars.add(memberBar);
				}
				if (!bars.isEmpty() && !teammatesToggleAdded)
				{
					teammatesToggleAdded = true;
					JButton contributors = smallButton("Contributors  " + (teammatesExpanded ? "▾" : "▸"));
					contributors.setHorizontalAlignment(SwingConstants.LEFT);
					contributors.addActionListener(e ->
					{
						teammatesExpanded = !teammatesExpanded;
						rebuild();
						revalidate();
						repaint();
					});
					add(Box.createVerticalStrut(2));
					add(contributors);
				}
				if (teammatesExpanded)
				{
					for (MemberBar memberRow : bars)
					{
						add(Box.createVerticalStrut(2));
						add(memberRow);
					}
				}
			}
		}

		// Who ticked the tile sits right under the bars, before any foldouts.
		if (teamView && merged.manual)
		{
			StringBuilder tickedBy = new StringBuilder();
			for (Map.Entry<String, TileProgress> entry : members.entrySet())
			{
				if (entry.getValue().manual)
				{
					if (tickedBy.length() > 0)
					{
						tickedBy.append(", ");
					}
					tickedBy.append(entry.getKey());
				}
			}
			BingoWrappedLabel tickedByLabel = new BingoWrappedLabel("Ticked off by: " + tickedBy, widthBasis);
			add(Box.createVerticalStrut(2));
			add(tickedByLabel);
		}

		// Long item and source lists live behind a toggle - but only when the goal labels
		// don't already say everything, so simple tiles stay clutter-free.
		// Each entry is {full goal description or null, received items or null}.
		List<String[]> extraInfo = new ArrayList<>();
		for (int g = 0; g < tile.goals.size(); g++)
		{
			BingoGoal goal = tile.goals.get(g);
			GoalProgress p = merged.goal(g, tile.goals.size());
			String description = goal.hasExtraDetail() ? goal.describe() : null;
			String received = goal.usesMatchedSet() && p.matched != null && !p.matched.isEmpty()
				? "Received: " + String.join(", ", sortedNames(p.matched))
				: null;
			if (description != null || received != null)
			{
				extraInfo.add(new String[]{description, received});
			}
		}

		if (!extraInfo.isEmpty())
		{
			add(Box.createVerticalStrut(6));
			JButton detailsToggle = smallButton(detailsExpanded ? "Details  ▾" : "Details  ▸");
			detailsToggle.setHorizontalAlignment(SwingConstants.LEFT);
			detailsToggle.addActionListener(e ->
			{
				detailsExpanded = !detailsExpanded;
				rebuild();
				revalidate();
				repaint();
			});
			add(detailsToggle);

			if (detailsExpanded)
			{
				for (int i = 0; i < extraInfo.size(); i++)
				{
					String[] info = extraInfo.get(i);
					int topGap = i == 0 ? 4 : 6;
					if (info[0] != null)
					{
						BingoWrappedLabel infoLabel = new BingoWrappedLabel(info[0], widthBasis - 8);
						infoLabel.setBorder(BorderFactory.createEmptyBorder(topGap, 8, 0, 0));
						add(infoLabel);
						topGap = 0;
					}
					if (info[1] != null)
					{
						BingoWrappedLabel receivedLabel = new BingoWrappedLabel(info[1], widthBasis - 8);
						receivedLabel.setForeground(BingoUi.COLOR_GOAL_DONE);
						receivedLabel.setBorder(BorderFactory.createEmptyBorder(topGap, 8, 0, 0));
						add(receivedLabel);
					}
				}
			}
		}

		add(Box.createVerticalStrut(6));

		// On a store team every completion claim goes through an admin, so the manual
		// tick disappears entirely - a self-serve tick would bypass the review the
		// Requests tab exists for. Party-only teams keep it (there is no reviewer).
		final int tileIndex = selectedTile;
		final boolean ownTicked = own.manual;
		JButton tick = null;
		if (!plugin.storeConfigured())
		{
			tick = smallButton(ownTicked ? "Remove manual tick" : "Tick off tile (manual)");
			tick.setToolTipText(ownTicked
				? "Un-tick this tile (your manual completion is removed team-wide)"
				: "Mark this tile completed by hand (for tiles the tracker can't count)");
			tick.addActionListener(e -> plugin.setManualComplete(tileIndex, !ownTicked));
		}

		JButton request = smallButton(requestInFlight ? "Sending request..." : "Request admin credit");
		request.setEnabled(plugin.storeConfigured() && !requestInFlight);
		request.addActionListener(e -> requestCredit(tileIndex, tile));

		JButton reset = smallButton("Reset tile progress");
		reset.addActionListener(e ->
		{
			int answer = JOptionPane.showConfirmDialog(this,
				"Reset all tracked progress on this tile?", "Irons Pub Bingo", JOptionPane.YES_NO_OPTION);
			if (answer == JOptionPane.YES_OPTION)
			{
				plugin.resetTileProgress(tileIndex);
			}
		});

		// All tile actions behind one foldout; its state survives the constant detail
		// rebuilds via the actionsExpanded field.
		JButton actionsToggle = smallButton("Actions  " + (actionsExpanded ? "▾" : "▸"));
		actionsToggle.setHorizontalAlignment(SwingConstants.LEFT);
		JPanel actionsCard = new JPanel();
		actionsCard.setLayout(new BoxLayout(actionsCard, BoxLayout.Y_AXIS));
		actionsCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actionsCard.setAlignmentX(LEFT_ALIGNMENT);
		if (tick != null)
		{
			actionsCard.add(tick);
			actionsCard.add(Box.createVerticalStrut(4));
		}
		actionsCard.add(request);
		actionsCard.add(Box.createVerticalStrut(4));
		actionsCard.add(reset);
		actionsCard.setVisible(actionsExpanded);
		actionsToggle.addActionListener(e ->
		{
			actionsExpanded = !actionsCard.isVisible();
			actionsCard.setVisible(actionsExpanded);
			actionsToggle.setText("Actions  " + (actionsExpanded ? "▾" : "▸"));
			revalidate();
			repaint();
		});
		add(actionsToggle);
		add(Box.createVerticalStrut(4));
		add(actionsCard);
		return true;
	}

	/** Dialog for a credit request: amount or completion, plus a note for the admin. */
	private void requestCredit(int tileIndex, BingoTile tile)
	{
		JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
		JComboBox<String> goalBox = null;
		if (tile.goals.size() > 1)
		{
			String[] labels = new String[tile.goals.size()];
			for (int g = 0; g < tile.goals.size(); g++)
			{
				labels[g] = (g + 1) + ". " + tile.goals.get(g).shortDescribe();
			}
			goalBox = new JComboBox<>(labels);
			form.add(new JLabel("Goal:"));
			form.add(goalBox);
		}
		JTextField amount = new JTextField();
		JCheckBox complete = new JCheckBox("Mark the whole tile complete instead");
		JTextField note = new JTextField();
		JTextField links = new JTextField();
		JCheckBox proofShot = new JCheckBox("Attach a screenshot (posts to your Discord webhook)");
		proofShot.setEnabled(plugin.webhookConfigured());
		proofShot.setToolTipText(plugin.webhookConfigured()
			? "Screenshots the game, posts it to your Discord webhook and files its link as proof"
			: "Set a Discord webhook in the settings first");
		form.add(new JLabel("Amount to credit (e.g. 40):"));
		form.add(amount);
		form.add(complete);
		form.add(new JLabel("Note for the admin (e.g. laps 0 to 40):"));
		form.add(note);
		form.add(new JLabel("Proof link(s) - screenshots on Discord/Imgur:"));
		form.add(links);
		form.add(proofShot);

		int answer = JOptionPane.showConfirmDialog(this, form,
			"Request admin credit - " + tile.label, JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
		if (answer != JOptionPane.OK_OPTION)
		{
			return;
		}
		Long add = null;
		String amountText = amount.getText().trim();
		if (!amountText.isEmpty())
		{
			try
			{
				add = Long.parseLong(amountText);
			}
			catch (NumberFormatException e)
			{
				JOptionPane.showMessageDialog(this, "Amount must be a whole number.",
					"Irons Pub Bingo", JOptionPane.WARNING_MESSAGE);
				return;
			}
		}
		if (add == null && !complete.isSelected())
		{
			JOptionPane.showMessageDialog(this,
				"Fill in an amount, or tick \"mark the whole tile complete\".",
				"Irons Pub Bingo", JOptionPane.WARNING_MESSAGE);
			return;
		}
		Integer goalIndex = goalBox == null ? null : goalBox.getSelectedIndex();
		requestInFlight = true;
		rebuild();
		revalidate();
		repaint();
		final Long addFinal = add;
		final String noteText = note.getText().trim();
		final String manualLinks = links.getText().trim();
		if (proofShot.isSelected())
		{
			// Screenshot first, so its Discord link rides along as a proof link. A failed
			// screenshot never blocks the request itself.
			String what = complete.isSelected() ? "tile complete" : "+" + addFinal;
			String goalPart = goalIndex == null ? ""
				: " on goal " + (goalIndex + 1) + " (" + tile.goals.get(goalIndex).shortDescribe() + ")";
			String detail = tile.label + " (" + what + goalPart + ")";
			plugin.postProofScreenshot(detail, (link, shotError) -> SwingUtilities.invokeLater(() ->
				sendRequest(tileIndex, goalIndex, addFinal, complete.isSelected(), noteText,
					link == null ? manualLinks : manualLinks.isEmpty() ? link : manualLinks + " " + link,
					shotError)));
		}
		else
		{
			sendRequest(tileIndex, goalIndex, addFinal, complete.isSelected(), noteText, manualLinks, null);
		}
	}

	private void sendRequest(int tileIndex, Integer goalIndex, Long add, boolean complete,
		String note, String links, String screenshotError)
	{
		plugin.submitCreditRequest(tileIndex, goalIndex, add, complete, note, links,
			(ok, error) -> SwingUtilities.invokeLater(() ->
			{
				requestInFlight = false;
				rebuild();
				revalidate();
				repaint();
				String message = ok ? "Request sent - a team admin will review it on the sheet."
					: "Could not send the request: " + error;
				if (ok && screenshotError != null)
				{
					message += "\nThe screenshot didn't attach (" + screenshotError
						+ ") - add a proof link yourself if the admin needs one.";
				}
				JOptionPane.showMessageDialog(this, message, "Irons Pub Bingo",
					ok && screenshotError == null ? JOptionPane.INFORMATION_MESSAGE : JOptionPane.WARNING_MESSAGE);
			}));
	}

	/**
	 * A thin per-member bar: fill fraction behind, name left, count right. The name gets
	 * every pixel the count doesn't need (clipped with ".." only when truly out of room).
	 */
	private static class MemberBar extends JPanel
	{
		private final String name;
		private final String count;
		private final float fraction;

		MemberBar(String name, String count, float fraction, int widthBasis)
		{
			this.name = name;
			this.count = count;
			this.fraction = fraction;
			setPreferredSize(new Dimension(widthBasis, 14));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 14));
			setMinimumSize(new Dimension(40, 14));
			setAlignmentX(LEFT_ALIGNMENT);
			setFont(FontManager.getRunescapeSmallFont());
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			int w = getWidth();
			int h = getHeight();
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, w, h);
			g.setColor(fraction >= 1f ? BingoUi.COLOR_COMPLETE : BingoUi.COLOR_PARTIAL);
			g.fillRect(0, 0, Math.round(w * Math.max(0f, Math.min(1f, fraction))), h);

			java.awt.FontMetrics metrics = g.getFontMetrics(getFont());
			int baseline = (h + metrics.getAscent() - metrics.getDescent()) / 2;
			int countWidth = metrics.stringWidth(count);
			String shownName = name;
			int available = w - countWidth - 12;
			if (metrics.stringWidth(shownName) > available)
			{
				while (shownName.length() > 1
					&& metrics.stringWidth(shownName + "..") > available)
				{
					shownName = shownName.substring(0, shownName.length() - 1);
				}
				shownName += "..";
			}
			g.setFont(getFont());
			g.setColor(Color.BLACK);
			g.drawString(shownName, 5, baseline + 1);
			g.drawString(count, w - countWidth - 3, baseline + 1);
			g.setColor(Color.WHITE);
			g.drawString(shownName, 4, baseline);
			g.drawString(count, w - countWidth - 4, baseline);
		}
	}

	/** Compact verified marker, falling back to text if the font lacks the checkmark glyph. */
	private static String verifiedMark()
	{
		return FontManager.getRunescapeSmallFont().canDisplay('✔') ? " ✔" : " (v)";
	}

	/** A progress bar styled for the panel: complete bars go green, partial ones amber. */
	private ProgressBar progressBar(long value, long target, int height)
	{
		ProgressBar bar = new ProgressBar();
		bar.setMaximumValue((int) Math.max(1, Math.min(Integer.MAX_VALUE, target)));
		bar.setValue((int) Math.max(0, Math.min(Integer.MAX_VALUE, value)));
		bar.setForeground(value >= target ? BingoUi.COLOR_COMPLETE : BingoUi.COLOR_PARTIAL);
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setFont(FontManager.getRunescapeSmallFont());
		bar.setPreferredSize(new Dimension(widthBasis, height));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		bar.setMinimumSize(new Dimension(40, height));
		bar.setAlignmentX(LEFT_ALIGNMENT);
		return bar;
	}

	/** Received item names, alphabetical and case-insensitive, for stable display. */
	private static List<String> sortedNames(java.util.Collection<String> names)
	{
		List<String> sorted = new ArrayList<>(names);
		sorted.sort(String.CASE_INSENSITIVE_ORDER);
		return sorted;
	}

	/** Compact counts so bar labels stay inside the bar: 1500 -> 1.5k, 5000000 -> 5M. */
	private static String formatCount(long value)
	{
		if (value >= 1_000_000)
		{
			double millions = value / 1_000_000d;
			return (millions == Math.floor(millions) ? String.valueOf((long) millions)
				: String.format("%.1f", millions)) + "M";
		}
		if (value >= 10_000)
		{
			return (value / 1000) + "k";
		}
		return String.valueOf(value);
	}

	private static JButton smallButton(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setAlignmentX(LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		button.setFocusable(false);
		return button;
	}
}

package com.ironspubbingo;

import java.util.HashMap;
import java.util.Map;

/**
 * Everything known about one team member's progress: display name and their tile shares.
 * Keyed by the member's account hash in the team cache, party messages and the team store,
 * so display name changes don't split a member's contribution.
 */
class TeamMemberState
{
	String name;
	Map<Integer, TileProgress> tiles;

	Map<Integer, TileProgress> tilesMap()
	{
		if (tiles == null)
		{
			tiles = new HashMap<>();
		}
		return tiles;
	}

	/**
	 * Applies incoming tile shares last-write-wins by the owner's timestamp.
	 *
	 * @return whether anything changed
	 */
	boolean apply(String newName, Map<Integer, TileProgress> incoming, int maxTiles)
	{
		boolean changed = false;
		if (newName != null && !newName.isEmpty() && !newName.equals(name))
		{
			name = newName;
			changed = true;
		}
		if (incoming == null)
		{
			return changed;
		}
		for (Map.Entry<Integer, TileProgress> entry : incoming.entrySet())
		{
			Integer tile = entry.getKey();
			TileProgress share = entry.getValue();
			if (tile == null || share == null || tile < 0 || tile >= maxTiles)
			{
				continue;
			}
			TileProgress current = tilesMap().get(tile);
			if (current == null || ts(share) > ts(current))
			{
				tilesMap().put(tile, share);
				changed = true;
			}
		}
		return changed;
	}

	private static long ts(TileProgress p)
	{
		return p.ts == null ? 0 : p.ts;
	}
}

package com.ironspubbingo;

/**
 * The kinds of automatically (or manually) trackable goals a bingo tile can contain.
 */
public enum GoalType
{
	/** Receive specific item drops, optionally restricted to certain sources. */
	DROP,
	/** Receive rare "purple" uniques from raids. */
	RAID_PURPLE,
	/** Gain kill count on bosses/activities that print kill count chat messages. */
	KC,
	/** Kill any NPC (including regular monsters): counts deaths of NPCs you damaged. */
	KILL,
	/** Receive pets (any pet, or specific ones via collection log messages). */
	PET,
	/** Gain a set amount of experience in a skill. */
	XP,
	/** Complete laps of a rooftop/agility course (detected like RuneLite's lap counter). */
	LAP,
	/** Receive a single drop/loot pile worth at least a set GE value. */
	VALUE,
	/** Match a game chat message against a regex (speed times, delve levels, quest completions, ...). */
	CHAT,
	/** Not automatically trackable; the player ticks the tile off by hand. */
	MANUAL,
}

package com.ironspubbingo;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Locale;

/**
 * A bingo board, deserialized from the shareable board JSON.
 */
public class BingoBoard
{
	String name;
	/**
	 * Optional stable identifier. Boards sharing an id share progress and team sync, so a
	 * host can edit the board mid-event without resetting anyone — labels, icons, points,
	 * targets, even what a tile tracks — as long as tiles keep their position (edit in
	 * place, don't insert or reorder). Only a new id (or removing it) is a new board.
	 */
	String id;
	/** Optional board revision, shown next to the board name. */
	Integer version;
	/** Optional event start (ISO 8601, e.g. "2026-08-29T18:00Z"). Tracking only counts after it. */
	String start;
	/** Optional event end. Tracking stops counting once passed. */
	String end;
	/** Optional bonus points per completed bingo line (row, column or diagonal). */
	Integer linePoints;
	/** Whether the two diagonals count as bingo lines. Default true. */
	Boolean diagonals;
	/** Optional bonus points for completing the whole board. */
	Integer blackoutPoints;
	int size;
	List<BingoTile> tiles;

	transient String normalizedId;
	transient Instant startTime;
	transient Instant endTime;

	/**
	 * Parses and validates a board.
	 *
	 * @return the parsed board
	 * @throws IllegalArgumentException with a user-facing message when invalid
	 */
	static BingoBoard parse(Gson gson, String json)
	{
		BingoBoard board;
		try
		{
			board = gson.fromJson(json, BingoBoard.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new IllegalArgumentException("Not valid JSON: " + e.getMessage());
		}
		if (board == null)
		{
			throw new IllegalArgumentException("Board is empty");
		}
		String err = board.validate();
		if (err != null)
		{
			throw new IllegalArgumentException(err);
		}
		return board;
	}

	private String validate()
	{
		if (name == null || name.trim().isEmpty())
		{
			name = "Irons Pub Bingo";
		}
		if (id != null && !id.trim().isEmpty())
		{
			String normalized = id.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9-_]", "");
			if (normalized.isEmpty())
			{
				return "Board id must contain letters, numbers, '-' or '_'";
			}
			if (normalized.length() > 40)
			{
				return "Board id is too long (max 40 characters)";
			}
			normalizedId = normalized;
		}
		if (version != null && version < 0)
		{
			return "'version' must not be negative";
		}
		if (start != null && !start.trim().isEmpty())
		{
			try
			{
				startTime = parseTime(start);
			}
			catch (DateTimeParseException e)
			{
				return "Could not read 'start' (" + start + ") - use e.g. 2026-08-29T18:00Z";
			}
		}
		if (end != null && !end.trim().isEmpty())
		{
			try
			{
				endTime = parseTime(end);
			}
			catch (DateTimeParseException e)
			{
				return "Could not read 'end' (" + end + ") - use e.g. 2026-09-07T20:00Z";
			}
		}
		if (startTime != null && endTime != null && !endTime.isAfter(startTime))
		{
			return "'end' must be after 'start'";
		}
		if (linePoints != null && linePoints < 0)
		{
			return "'linePoints' must not be negative";
		}
		if (blackoutPoints != null && blackoutPoints < 0)
		{
			return "'blackoutPoints' must not be negative";
		}
		if (size < 1 || size > 10)
		{
			return "Board size must be between 1 and 10 (got " + size + ")";
		}
		if (tiles == null || tiles.size() != size * size)
		{
			return "A " + size + "x" + size + " board needs exactly " + (size * size)
				+ " tiles (got " + (tiles == null ? 0 : tiles.size()) + ")";
		}
		for (int i = 0; i < tiles.size(); i++)
		{
			BingoTile tile = tiles.get(i);
			if (tile == null)
			{
				return "tile " + (i + 1) + ": empty tile";
			}
			String err = tile.validate(i);
			if (err != null)
			{
				return err;
			}
		}
		return null;
	}

	/**
	 * Accepts ISO 8601 instants leniently: "2026-08-29" (midnight UTC), "2026-08-29T18:00Z"
	 * (seconds optional, UTC assumed when no zone given) and explicit offsets.
	 */
	static Instant parseTime(String raw)
	{
		String v = raw.trim();
		if (v.matches("\\d{4}-\\d{2}-\\d{2}"))
		{
			return LocalDate.parse(v).atStartOfDay(ZoneOffset.UTC).toInstant();
		}
		if (v.matches(".*T\\d{2}:\\d{2}"))
		{
			v += ":00";
		}
		else if (v.matches(".*T\\d{2}:\\d{2}Z"))
		{
			v = v.substring(0, v.length() - 1) + ":00Z";
		}
		if (!v.endsWith("Z") && !v.matches(".*[+-]\\d{2}:?\\d{2}$"))
		{
			v += "Z";
		}
		try
		{
			return Instant.parse(v);
		}
		catch (DateTimeParseException e)
		{
			return OffsetDateTime.parse(v).toInstant();
		}
	}

	/**
	 * The key progress and team sync are stored under. Without an id, any edit at all is a
	 * new board. With one, the id IS the board: hosts may tune tiles mid-event without a
	 * reset. Tampering is not this key's job - the store rejects any client whose exact
	 * board code differs from the host's, and that gate is what keeps store events honest.
	 */
	String storageKey(Gson gson)
	{
		if (normalizedId == null)
		{
			return Integer.toHexString(gson.toJson(this).hashCode());
		}
		return identityKey();
	}

	/** The board's identity across revisions (its host-set id), or null when it has none. */
	String identityKey()
	{
		return normalizedId == null ? null : "id_" + normalizedId;
	}

	int linePointsValue()
	{
		return linePoints == null || linePoints < 0 ? 0 : linePoints;
	}

	int blackoutPointsValue()
	{
		return blackoutPoints == null || blackoutPoints < 0 ? 0 : blackoutPoints;
	}

	/** Rows + columns, plus both diagonals when they count. */
	int maxLines()
	{
		return 2 * size + (diagonalsCount() ? 2 : 0);
	}

	boolean diagonalsCount()
	{
		return diagonals == null || diagonals;
	}

	String getName()
	{
		return name;
	}

	int getSize()
	{
		return size;
	}

	List<BingoTile> getTiles()
	{
		return tiles;
	}
}

