package com.ironspubbingo;

import java.awt.BorderLayout;
import java.awt.Graphics;
import javax.swing.JPanel;

/**
 * One tile cell on the board grid. Optionally paints a bottom-up fill showing the tile's
 * partial progress, like a progress bar inside the tile.
 */
class BingoTileCell extends JPanel
{
	private float fillFraction;

	BingoTileCell()
	{
		super(new BorderLayout());
	}

	void setFillFraction(float fillFraction)
	{
		if (this.fillFraction != fillFraction)
		{
			this.fillFraction = fillFraction;
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (fillFraction > 0f)
		{
			int fillHeight = Math.round(getHeight() * Math.min(1f, fillFraction));
			g.setColor(BingoUi.COLOR_PARTIAL);
			g.fillRect(0, getHeight() - fillHeight, getWidth(), fillHeight);
		}
	}
}

package com.ironspubbingo;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * Agility courses whose laps can be counted: a lap completes when Agility XP lands while
 * the player stands on the course's end tile(s), with the course identified by map region —
 * the same detection RuneLite's own Agility plugin uses.
 *
 * Region ids and end tiles adapted from RuneLite's agility plugin Courses
 * (BSD-2, Copyright (c) 2018, Seth <http://github.com/sethtroll>).
 */
enum BingoCourse
{
	GNOME("Gnome Stronghold", 9781, point(2484, 3437, 0), point(2487, 3437, 0)),
	SHAYZIEN_BASIC("Shayzien Basic", 6200, point(1554, 3640, 0)),
	DRAYNOR("Draynor Village", 12338, point(3103, 3261, 0)),
	AL_KHARID("Al Kharid", 13105, point(3299, 3194, 0)),
	PYRAMID("Agility Pyramid", 13356, point(3364, 2830, 0)),
	VARROCK("Varrock", 12853, point(3236, 3417, 0)),
	PENGUIN("Penguin", 10559, point(2652, 4039, 1)),
	BARBARIAN("Barbarian Outpost", 10039, point(2543, 3553, 0)),
	CANIFIS("Canifis", 13878, point(3510, 3485, 0)),
	APE_ATOLL("Ape Atoll", 11050, point(2770, 2747, 0)),
	SHAYZIEN_ADVANCED("Shayzien Advanced", 5944, point(1522, 3625, 0)),
	FALADOR("Falador", 12084,
		point(3029, 3332, 0), point(3029, 3333, 0), point(3029, 3334, 0), point(3029, 3335, 0)),
	WILDERNESS("Wilderness", 11837,
		point(2993, 3933, 0), point(2994, 3933, 0), point(2995, 3933, 0)),
	WEREWOLF("Werewolf", 14234, point(3528, 9873, 0)),
	SEERS("Seers' Village", 10806, point(2704, 3464, 0)),
	POLLNIVNEACH("Pollnivneach", 13358, point(3363, 2998, 0)),
	RELLEKKA("Rellekka", 10553, point(2653, 3676, 0)),
	PRIFDDINAS("Prifddinas", 12895, point(3240, 6109, 0)),
	ARDOUGNE("Ardougne", 10547, point(2668, 3297, 0));

	private static final Map<Integer, BingoCourse> BY_REGION = new HashMap<>();
	private static final Map<String, BingoCourse> BY_NAME = new HashMap<>();

	private final String displayName;
	private final int regionId;
	private final WorldPoint[] endPoints;

	static
	{
		for (BingoCourse course : values())
		{
			BY_REGION.put(course.regionId, course);
			BY_NAME.put(normalize(course.name()), course);
			BY_NAME.put(normalize(course.displayName), course);
		}
		// Common spellings and shorthands hosts will type
		BY_NAME.put(normalize("Gnome"), GNOME);
		BY_NAME.put(normalize("Draynor"), DRAYNOR);
		BY_NAME.put(normalize("Seers"), SEERS);
		BY_NAME.put(normalize("Seers Village"), SEERS);
		BY_NAME.put(normalize("Relleka"), RELLEKKA);
		BY_NAME.put(normalize("Prif"), PRIFDDINAS);
		BY_NAME.put(normalize("Barbarian"), BARBARIAN);
		BY_NAME.put(normalize("Pyramid"), PYRAMID);
	}

	BingoCourse(String displayName, int regionId, WorldPoint... endPoints)
	{
		this.displayName = displayName;
		this.regionId = regionId;
		this.endPoints = endPoints;
	}

	private static WorldPoint point(int x, int y, int plane)
	{
		return new WorldPoint(x, y, plane);
	}

	private static String normalize(String value)
	{
		return value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	static BingoCourse fromName(String name)
	{
		return name == null ? null : BY_NAME.get(normalize(name));
	}

	static BingoCourse forRegion(int regionId)
	{
		return BY_REGION.get(regionId);
	}

	boolean isEndPoint(WorldPoint location)
	{
		for (WorldPoint end : endPoints)
		{
			if (end.equals(location))
			{
				return true;
			}
		}
		return false;
	}

	String getDisplayName()
	{
		return displayName;
	}
}

package com.ironspubbingo;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * One tile on the bingo board, deserialized from the board JSON.
 */
public class BingoTile
{
	/** Short label shown on the board, e.g. "5x Ancient Pages from Mith Drags". */
	String label;
	/** Optional longer rules text shown in the tile detail view. */
	String description;
	/** "ALL" (default) = every goal must complete; "ANY" = one goal is enough (for "X or Y" tiles). */
	String mode;
	/** Optional tile icon: an item ID (number) or an exact item name (string, tradeables only). */
	Object icon;
	/** Optional points awarded for completing this tile. */
	Integer points;
	List<BingoGoal> goals;

	transient boolean anyMode;
	/** Item ID given directly in the board file, or -1. */
	transient int iconItemId = -1;
	/** Item name still to be resolved to an ID at render time, or null. */
	transient String iconName;
	/** Cached result of resolving {@link #iconName}: 0 = not tried, -1 = not found. */
	transient int resolvedIconId;

	String validate(int tileIndex)
	{
		String where = "tile " + (tileIndex + 1);
		if (label == null || label.trim().isEmpty())
		{
			return where + ": missing label";
		}
		if (mode != null)
		{
			String m = mode.trim().toUpperCase(Locale.ROOT);
			if (!m.equals("ALL") && !m.equals("ANY"))
			{
				return where + ": mode must be ALL or ANY";
			}
			anyMode = m.equals("ANY");
		}
		if (points != null && points < 0)
		{
			return where + ": points must not be negative";
		}
		if (icon instanceof Number)
		{
			iconItemId = ((Number) icon).intValue();
		}
		else if (icon instanceof String)
		{
			String s = ((String) icon).trim();
			if (!s.isEmpty())
			{
				try
				{
					iconItemId = Integer.parseInt(s);
				}
				catch (NumberFormatException e)
				{
					iconName = s;
				}
			}
		}
		if (goals == null || goals.isEmpty())
		{
			// A tile without goals is a manual tile.
			goals = new ArrayList<>();
			BingoGoal manual = new BingoGoal();
			manual.type = "MANUAL";
			goals.add(manual);
		}
		for (int g = 0; g < goals.size(); g++)
		{
			BingoGoal goal = goals.get(g);
			if (goal == null)
			{
				return where + ", goal " + (g + 1) + ": empty goal";
			}
			String err = goal.validate();
			if (err != null)
			{
				return where + " (\"" + label + "\"), goal " + (g + 1) + ": " + err;
			}
		}
		return null;
	}

	int pointsValue()
	{
		return points == null || points < 0 ? 0 : points;
	}

	/** What this tile TRACKS - goal signatures in order. Labels and points don't count. */
	String trackingSignature()
	{
		StringBuilder sig = new StringBuilder();
		for (BingoGoal goal : goals)
		{
			sig.append(sig.length() > 0 ? ";" : "").append(goal.trackingSignature());
		}
		return sig.toString();
	}

	boolean isComplete(TileProgress progress)
	{
		if (progress.manual)
		{
			return true;
		}
		boolean sawManual = false;
		for (int i = 0; i < goals.size(); i++)
		{
			BingoGoal goal = goals.get(i);
			if (goal.goalType == GoalType.MANUAL)
			{
				sawManual = true;
				continue;
			}
			boolean done = goal.isComplete(progress.goal(i, goals.size()));
			if (anyMode && done)
			{
				return true;
			}
			if (!anyMode && !done)
			{
				return false;
			}
		}
		// ALL mode: complete unless a MANUAL goal is present (those require the manual tick).
		// ANY mode: nothing matched.
		return !anyMode && !sawManual;
	}
}

package com.ironspubbingo;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.Collections;
import java.util.List;
import javax.swing.JPanel;

/**
 * The bingo grid container: hosts the tile cells and paints translucent strokes straight
 * through completed bingo lines on top of them, classic bingo-card style, so it is obvious
 * which row/column/diagonal a completed line runs along.
 */
class BingoGridPanel extends JPanel
{
	private static final Color LINE_COLOR = new Color(
		BingoUi.COLOR_LINE.getRed(), BingoUi.COLOR_LINE.getGreen(), BingoUi.COLOR_LINE.getBlue(), 170);

	private int boardSize;
	/** Completed lines as {firstCellIndex, lastCellIndex} pairs. */
	private List<int[]> lineSegments = Collections.emptyList();

	void setLines(int boardSize, List<int[]> lineSegments)
	{
		this.boardSize = boardSize;
		this.lineSegments = lineSegments;
		repaint();
	}

	@Override
	protected void paintChildren(Graphics g)
	{
		super.paintChildren(g);
		if (lineSegments.isEmpty() || boardSize <= 0 || getComponentCount() < boardSize * boardSize)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(LINE_COLOR);
		g2.setStroke(new BasicStroke(Math.max(4f, getWidth() / (boardSize * 14f)),
			BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int[] segment : lineSegments)
		{
			Point from = cellCenter(segment[0]);
			Point to = cellCenter(segment[1]);
			g2.drawLine(from.x, from.y, to.x, to.y);
		}
		g2.dispose();
	}

	private Point cellCenter(int cellIndex)
	{
		Rectangle bounds = getComponent(cellIndex).getBounds();
		return new Point(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2);
	}
}
